CREATE TABLE "donations" (
    "donationid" text NOT NULL,
    "projectid" text,
    "donor_acctid" text,
    "donor_city" text,
    "donor_state" text,
    "donor_zip" text,
    "is_teacher_acct" text,
    "donation_timestamp" timestamp with time zone,
    "donation_to_project" real,
    "donation_optional_support" real,
    "donation_total" real,
    "dollar_amount" text,
    "donation_included_optional_support" text,
    "payment_method" text,
    "payment_included_acct_credit" text,
    "payment_included_campaign_gift_card" text,
    "payment_included_web_purchased_gift_card" text,
    "payment_was_promo_matched" text,
    "via_giving_page" text,
    "for_honoree" text,
    "donation_message" text,
    PRIMARY KEY ("donationid")
);

CREATE TABLE "essays" (
    "projectid" text,
    "teacher_acctid" text,
    "title" text,
    "short_description" text,
    "need_statement" text,
    "essay" text
);

CREATE TABLE "projects" (
    "projectid" text NOT NULL,
