CREATE TABLE "resources" (
    "resourceid" text NOT NULL,
    "projectid" text,
    "vendorid" bigint,
    "vendor_name" text,
    "project_resource_type" text,
    "item_name" text,
    "item_number" text,
    "item_unit_price" real,
    "item_quantity" bigint,
